/**
 * 把 pdf.js 的 worker 从 unpkg 换成本站那份。
 *
 * 为什么需要这么一个"补丁"：Fresh Air PDF 在**模块初始化时**无条件写下
 *   `GlobalWorkerOptions.workerSrc = "https://unpkg.com/pdfjs-dist@<ver>/build/pdf.worker.min.mjs"`
 * （它自己那份 pdf.js 的 `_createCDNWrapper` 逻辑），`config.workerUrl` 在文档里写了但代码里没人读。
 * 展馆内网、弱网、墙内取不到 unpkg，结果是打开 PDF 只有一行
 * `Failed to load PDF: Setting up fake worker failed`（页面全白）。
 *
 * 做法：在库加载**之前**包一层 `globalThis.Worker`，把指向 unpkg 的 worker URL 换成站点内的
 * `pdfjs/pdf.worker.min.mjs`（由 `scripts/stage-assets.mjs` 从 `fresh-air-pdf/dist/` 复制，版本天然一致）。
 * pdf.js 的 worker 文件自带"我是不是被当 worker 跑"的检测，所以同一个文件既能当 worker 也能当模块。
 *
 * 只改 unpkg 那一个来源，其它 Worker 一律原样透传。
 */

/** 站点内 worker 的地址（跟随 BASE_URL，部署到子目录也有效）。 */
export function localPdfWorkerUrl(): string {
  const base = import.meta.env.BASE_URL.endsWith('/') ? import.meta.env.BASE_URL : `${import.meta.env.BASE_URL}/`;
  return `${base}pdfjs/pdf.worker.min.mjs`;
}

/** pdf.js 的 worker 在 unpkg 上（库默认值就是它）。 */
const CDN_HOST = 'unpkg.com';

let installed = false;

/**
 * 安装一次 Worker 包装。必须在 `import('fresh-air-pdf')` **之前**调用：
 * 阅读器一读文档就会去建 worker，晚了就赶不上。
 *
 * 用 `extends` 而不是改原型：子类天然满足 pdf.js 对 Worker 的全部形状要求
 * （`postMessage`/`terminate`/`onmessage`/静态成员都从原生类继承），只把 unpkg 那条 URL 换掉。
 */
export function installLocalPdfWorker(): void {
  if (installed || typeof window === 'undefined' || typeof window.Worker !== 'function') return;
  installed = true;
  const NativeWorker = window.Worker;
  const local = localPdfWorkerUrl();

  class MuseumWorker extends NativeWorker {
    constructor(url: string | URL, options?: WorkerOptions) {
      const resolved = String(url);
      // pdf.js 把**跨域**的 workerSrc（就是它写死的 unpkg）用 `_createCDNWrapper` 包成
      // `blob:` 模块再 `new Worker(blobUrl)`：所以这里既要认 unpkg，也要认 blob。
      // 全站只有 pdf.js 会创建 blob worker，直接换成站点内那份是安全的。
      const isPdfWorker = resolved.includes(CDN_HOST) || resolved.startsWith('blob:');
      if (isPdfWorker) {
        console.log('[pdf] redirect pdf.js worker ->', local);
        super(local, options);
        return;
      }
      super(url, options);
    }
  }

  console.log('[pdf] installLocalPdfWorker: window.Worker patched');
  try {
    window.Worker = MuseumWorker as unknown as typeof Worker;
  } catch {
    // 某些环境 window.Worker 是只读的：那就只能退回库自带的 CDN 行为。
  }
}
