import { lazy, Suspense } from 'react';
import type { ViewerConfig } from 'fresh-air-pdf';
import { ExternalLink } from 'lucide-react';
import { installLocalPdfWorker } from './pdfWorker';
import './archive.css';

/**
 * PDF 阅读器：用 **Fresh Air PDF**（[fresh-air-pdf](https://github.com/VeARCTechnologies/FRESH-AIR-PDF)，
 * MIT）——基于 Mozilla PDF.js 的 React 组件，自带翻页/缩放/缩略图/目录/全文搜索/选文字/适配宽度，
 * 我们只做一层薄封装：**懒加载** + 一行「在新标签打开」+ 只读配置。
 *
 * 两个必须处理的库行为（都已用无头浏览器实测踩到）：
 * 1. worker 默认指向 unpkg CDN，展馆内网/墙内取不到 → 打开 PDF 只有一行报错、页面全白。
 *    见 `pdfWorker.ts`：在库加载前把 `Worker` 包一层，把 unpkg 换成站点内的同版本 worker。
 * 2. 库很重：ESM 约 1.3 MB、样式（含整套 Font Awesome）约 1 MB、worker 另 1.3 MB。
 *    所以**必须懒加载**，且必须在那之前装好 worker 补丁。
 */
const FAPDFViewer = lazy(async () => {
  // 顺序要紧：先装 worker 补丁，再引入库（库一加载就把 workerSrc 写成 unpkg）。
  installLocalPdfWorker();
  // 样式由库自带（内含图标字体），跟着组件一起只在打开阅读器时加载。
  await import('fresh-air-pdf/style.css');
  const module = await import('fresh-air-pdf');
  return { default: module.FAPDFViewer };
});

/**
 * 博物馆场景的阅读配置：**只读**。
 * 标注/表单/签名是给"填表、审阅"用的；展项上要的是"看清楚这份档案"，
 * 开着反而让人以为可以改原件。搜索、缩略图、目录、选文字、拖动平移全部保留。
 */
const MUSEUM_READER_CONFIG: ViewerConfig = {
  readOnly: true,
  enableAnnotations: false,
  showToolbar: true,
  showThumbnails: true,
  showOutline: true,
  showSearch: true,
  enableTextSelection: true,
  enablePanning: true,
  virtualizePages: true,
  theme: 'light',
  // 只做类型导入，避免静态引入整个库（那会让上面的动态 import 失效、把 326 KB 拉回首屏）。
  // 字符串字面量不能直接赋给库里的字符串枚举，这里显式取它的类型。
  initialZoom: 'fit-width' as ViewerConfig['initialZoom'],
};

export function PdfReader({ url, title }: { url: string; title: string }) {
  return (
    <div className="pdf-reader" aria-label={`${title}阅读器`}>
      <Suspense fallback={<p className="viewer-loading">阅读器加载中</p>}>
        <FAPDFViewer document={url} config={MUSEUM_READER_CONFIG} className="pdf-reader-viewer" />
      </Suspense>
      <div className="pdf-reader-bar">
        <span>{title}</span>
        <a className="pdf-reader-open" href={url} target="_blank" rel="noreferrer">
          <ExternalLink />在新标签打开
        </a>
      </div>
    </div>
  );
}

export default PdfReader;
